////////////////////////////////////////////////////////////////////////////
//	Description : parameterized scheduled job — designer menu & icon
////////////////////////////////////////////////////////////////////////////

#include "parameterizedJob.h"

#include "backend/metaData.h"
#include "backend/backend_picture.h"   // ibBackendPicture::GetIconFromBase64 / GetPicture

bool ibValueMetaObjectParameterizedJob::CollectContextMenu(std::vector<ibMetaMenuItem>& items)
{
	items.emplace_back(ibMetaMenuKind::Module, wxT("ObjectModule"), _("Open object module"), m_propertyObjectModule->GetMetaObject());
	items.emplace_back(ibMetaMenuKind::Module, wxT("JobModule"), _("Open job module"), m_propertyManagerModule->GetMetaObject());
	return false;
}


/* PNG — the same clock the predefined kind wears: one subsystem, one visual. */
static const wxString s_parameterizedJob_16_png = wxT("");

wxIcon ibValueMetaObjectParameterizedJob::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectParameterizedJob::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_parameterizedJob_16_png, wxSize(16, 16));

	return icon;
}
